    // reflect_addReflectOff adds a pointer to the reflection offset lookup map.
    //
    //go:linkname reflect_addReflectOff reflect.addReflectOff
    int32_t reflect_addReflectOff(gocpp::unsafe_pointer ptr)
    {
        reflectOffsLock();
        if(reflectOffs.m == nullptr)
        {
            reflectOffs.m = gocpp::make(gocpp::Tag<gocpp::map<int32_t, gocpp::unsafe_pointer>>());
            reflectOffs.minv = gocpp::make(gocpp::Tag<gocpp::map<gocpp::unsafe_pointer, int32_t>>());
            reflectOffs.next = - 1;
        }
        auto [id, found] = reflectOffs.minv[ptr];
        if(! found)
        {
            id = reflectOffs.next;
            // use negative offsets as IDs to aid debugging
            reflectOffs.next--;
            reflectOffs.m[id] = ptr;
            reflectOffs.minv[ptr] = id;
        }
        reflectOffsUnlock();
        return id;
    }

    // reflect_adjustAIXGCDataForRuntime takes a type.GCData address and returns
    // the new address to use. This is only called on AIX.
    // See getGCMaskOnDemand.
    //
    //go:linknamestd reflect_adjustAIXGCDataForRuntime reflect.adjustAIXGCDataForRuntime
    unsigned char* reflect_adjustAIXGCDataForRuntime(unsigned char* addr)
    {
        return (unsigned char*)(add(gocpp::unsafe_pointer(addr), aixStaticDataBase - firstmoduledata.data));
    }

